import { SeedTsPaginationUriRequestParamsClient } from "@fern/ts-pagination-uri-request-params";

const client = new SeedTsPaginationUriRequestParamsClient({ baseUrl: "YOUR_BASE_URL" });
const pageableResponse = await client.users.listWithUriPagination("acct_1", {
    filter: "name",
    page_size: 2
});
for await (const item of pageableResponse) {
    console.log(item);
}

// Or you can manually iterate page-by-page
let page = await client.users.listWithUriPagination("acct_1", {
    filter: "name",
    page_size: 2
});
while (page.hasNextPage()) {
    page = page.getNextPage();
}

// You can also access the underlying response
const response = page.response;

